import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 5 Youth","description":"学习 让步从句与主句重心，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 5 Youth","description":"学习 让步从句与主句重心，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 让步从句与主句重心，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 4 Seeing hands","link":"/life/english/new-concept/book-4/unit-01/lesson-004"},"next":{"text":"第四册：流利英语 · Lesson 6 The sporting spirit","link":"/life/english/new-concept/book-4/unit-01/lesson-006"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 4 Seeing hands","link":"/life/english/new-concept/book-4/unit-01/lesson-004"},"next":{"text":"第四册：流利英语 · Lesson 6 The sporting spirit","link":"/life/english/new-concept/book-4/unit-01/lesson-006"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-01/lesson-005.md","filePath":"life/english/new-concept/book-4/unit-01/lesson-005.md"}'),i={name:"life/english/new-concept/book-4/unit-01/lesson-005.md"};function s(l,e,r,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第四册-流利英语-·-lesson-5-youth" tabindex="-1">第四册：流利英语 · Lesson 5 Youth <a class="header-anchor" href="#第四册-流利英语-·-lesson-5-youth" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 5 Youth&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕代际评价与青年经验展开，识别作者在谈论一个群体时使用的概括、例外和价值判断。练习用让步结构承认不同年龄的优势，而不把年龄当作决定人格的唯一原因。写作目标是有立场也有限定，能用一个具体情境代替空泛的“年轻人都如何”。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>generation</td><td>/ˌdʒenəˈreɪʃən/</td><td>n.</td><td>一代人</td><td>a younger generation</td></tr><tr><td>experience</td><td>/ɪkˈspɪəriəns/</td><td>n.</td><td>经验</td><td>practical experience</td></tr><tr><td>assumption</td><td>/əˈsʌmpʃən/</td><td>n.</td><td>假定</td><td>question an assumption</td></tr><tr><td>perspective</td><td>/pəˈspektɪv/</td><td>n.</td><td>视角</td><td>a fresh perspective</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>be open to — 愿意接受</li><li>take seriously — 认真对待</li></ul><h2 id="语法讲解-让步从句与主句重心" tabindex="-1">语法讲解：让步从句与主句重心 <a class="header-anchor" href="#语法讲解-让步从句与主句重心" aria-label="Permalink to &quot;语法讲解：让步从句与主句重心&quot;">​</a></h2><p>although 和 even though 引导让步从句，后面需要主语和谓语；despite 后接名词或动名词，不能直接接普通完整句。主句承载作者仍然坚持的判断，前面的让步不是取消主句。Although young people lack some experience, they can offer new ideas. 中承认经验不足，但重点是新想法。英语通常不在同一句使用 although 与 but 双重连接两个分句。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Although Lena had little experience, the team took her proposal seriously.</p></blockquote><p>虽然莉娜经验不多，团队仍认真考虑了她的提议。</p><p>although 从句提供让步背景；主句 took 为一般过去时，her proposal 是宾语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Although she was young, but she led the discussion. 应去掉 but；despite her youth 则不需要主谓结构。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>先读 although 从句，停一小拍再读主句；把 seriously 和 useful 等评价词重读，避免让背景盖过主要判断。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Although our new colleague lacks experience, she notices problems we overlook. Her questions helped us simplify a form. We should combine fresh perspectives with practical knowledge.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句比较新人和资深同事，包含让步、具体贡献和合作建议。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>让步后用具体表单案例支撑立场，避免对年龄群体作绝对评价。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：Despite ___ little experience, he asked useful questions.（have）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> having</p><p><strong>解析：</strong> despite 后可接动名词短语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例的主要信息是经验不足还是提议受到重视？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 提议受到重视。</p><p><strong>解析：</strong> 主句承担让步后仍成立的信息。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>改错：Although she disagreed, but she listened.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Although she disagreed, she listened.</p><p><strong>解析：</strong> although 与 but 不在此结构重复连接。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：让步从句与主句重心。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-004">上一课</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-01/lesson-006">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
